// The Rust engine for Android: UniFFI Kotlin bindings plus libmfcore.so per ABI.
// Both are generated by scripts/build-core-android.sh and are not checked in.
plugins {
    alias(libs.plugins.android.library)
}

android {
    namespace = "app.musicfetch.core"
    compileSdk = 37
    ndkVersion = "29.0.14206865"

    defaultConfig {
        minSdk = 29
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

val bindings = layout.projectDirectory.file("src/main/kotlin/app/musicfetch/core/mfcore.kt")
val nativeLibs = layout.projectDirectory.dir("src/main/jniLibs")
// Same property and default as :app's abiFilters.
val abis = providers.gradleProperty("musicfetch.abis").orElse("arm64-v8a,x86_64")

val checkCoreBuilt = tasks.register("checkCoreBuilt") {
    description = "Fails early when scripts/build-core-android.sh has not been run for every ABI."
    val bindingsFile = bindings.asFile
    val libsDir = nativeLibs.asFile
    val required = abis.map { list -> list.split(',').map { it.trim() }.filter { it.isNotEmpty() } }
    doLast {
        check(bindingsFile.isFile) { "mfcore bindings are missing. Run scripts/build-core-android.sh first." }
        val missing = required.get().filterNot { File(libsDir, "$it/libmfcore.so").isFile }
        check(missing.isEmpty()) {
            "libmfcore.so is missing for ${missing.joinToString()}. Run scripts/build-core-android.sh --abis ${required.get().joinToString(",")}."
        }
    }
}

tasks.named("preBuild") { dependsOn(checkCoreBuilt) }

dependencies {
    // UniFFI calls into libmfcore.so through JNA; the AAR carries libjnidispatch.so.
    api(libs.jna) { artifact { type = "aar" } }
    // The generated bindings expose suspend functions.
    api(libs.kotlinx.coroutines.android)
    // @RequiresApi on the API 33+ cleaner in the generated code.
    implementation(libs.androidx.annotation)
}
